import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadPlayfair } from "@remotion/google-fonts/PlayfairDisplay";
import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// CLIMATIZE · refrigeração e climatização, Petrolina e Vale do São Francisco. Sorteio: a 1ª ganhadora (Jane) já recebeu
// o ar-condicionado e vem outro sorteio para quem fizer qualquer serviço. Pedido em áudio do dono ((arquivo do cliente)).
// Identidade = vídeo anterior da própria Climatize (src/…video-2.mp4): fundo azul-marinho liso, ciano, ícones em vidro
// ciano, Montserrat forte + palavra de destaque em Playfair itálico, cena de céu com serras e mandacarus.
// Voz o locutor (src/voz-v1.mp3). Tempos = palavra na voz (edit/transcripts/voz-v1.json) + deslocamento do trecho:
// voz [0, 8.3) entra em 6.35 s; voz [8.3, fim) entra em 19.55 s. Trechos da entrega: public/climatize/entrega.mp4.

const { fontFamily: MS } = loadMontserrat("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: PF } = loadPlayfair("italic", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });

export const CZ_FPS = 30;
export const CZ_FRAMES = Math.round(44.2 * CZ_FPS);

const NAVY = "#14284A";
const NAVY_D = "#0C1A31";
const NAVY_L = "#244A78";
const CYAN = "#2BB8EA";
const CYAN_L = "#7FD8F7";
const BLUE = "#1A86CF";
const SKY_T = "#5CC0EA";
const SKY_B = "#CBEBF7";
const WHITE = "#FFFFFF";
const WA = "#25D366";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 18, stiffness = 150) =>
  spring({ frame: Math.round((t - a) * CZ_FPS), fps: CZ_FPS, config: { damping, stiffness } });
const VID = staticFile("climatize/entrega.mp4");

// ───────── texto ─────────
// palavra sobe de dentro da máscara e para
const Mask: React.FC<{ t: number; at: number; children: React.ReactNode; size: number; color?: string; serif?: boolean; weight?: number; ls?: string }> = ({ t, at, children, size, color = WHITE, serif, weight = 800, ls = "-0.01em" }) => {
  const s = sp(t, at, 200, 170);
  return (
    <span style={{ display: "inline-block", overflow: "hidden", verticalAlign: "bottom", padding: serif ? "0 0.14em 0.1em 0.06em" : "0 0.02em 0.04em", margin: serif ? "0 -0.08em" : 0 }}>
      <span style={{ display: "inline-block", transform: `translateY(${(1 - s) * 110}%)`, fontFamily: serif ? PF : MS, fontStyle: serif ? "italic" : "normal", fontWeight: serif ? 800 : weight,
        fontSize: size, lineHeight: 1.08, color, letterSpacing: serif ? "0" : ls, whiteSpace: "nowrap" }}>{children}</span>
    </span>
  );
};
type W = [string, number, boolean?];
const Line: React.FC<{ t: number; words: W[]; size: number; color?: string; accent?: string; gap?: number }> = ({ t, words, size, color = WHITE, accent = CYAN, gap = 0.26 }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: `0 ${gap}em`, fontSize: size }}>
    {words.map(([w, at, s], i) => <Mask key={i} t={t} at={at} size={size} serif={s} color={s ? accent : color}>{w}</Mask>)}
  </div>
);
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; op?: number }> = ({ top, gap = 0, children, op = 1 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: op }}>{children}</div>
);

// ───────── cena e transições ─────────
type Tr = "none" | "cut" | "circle" | "slideUp" | "wipe" | "zoom" | "iris";
const TD = 0.36;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; bg: string; cam?: [number, number]; drift?: number; origin?: string; children: React.ReactNode }> = ({ t, a, b, tr, bg, cam = [1, 1.05], drift = 0, origin = "50% 50%", children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" || tr === "cut" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 62%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 46}% ${(1 - q) * 40}% round ${(1 - q) * 220 + 0}px)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 130}% 0, ${q * 130 - 30}% 100%, 0 100%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.35 - 0.35 * q})`; op = Math.min(1, q * 1.8); }
  const p = lin(t, a - 0.3, b + TD);
  const z = cam[0] + (cam[1] - cam[0]) * p;
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden", background: bg }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})`, transformOrigin: origin }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const NavyBg: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(120% 75% at 50% 42%, ${NAVY_L} 0%, ${NAVY} 48%, ${NAVY_D} 100%)` }} />;

// céu do sertão (como no vídeo anterior da marca): degradê, serras e mandacarus
const Cactus: React.FC<{ x: number; y: number; h: number; flip?: boolean }> = ({ x, y, h, flip }) => (
  <svg width={h * 0.62} height={h} viewBox="0 0 62 100" style={{ position: "absolute", left: x, top: y - h, transform: flip ? "scaleX(-1)" : undefined }}>
    <g fill="#2E7D4F">
      <rect x={24} y={6} width={14} height={94} rx={7} />
      <rect x={4} y={34} width={12} height={34} rx={6} />
      <rect x={4} y={60} width={26} height={11} rx={5.5} />
      <rect x={46} y={22} width={12} height={34} rx={6} />
      <rect x={34} y={48} width={24} height={11} rx={5.5} />
    </g>
    <rect x={27} y={10} width={3} height={86} rx={1.5} fill="#3F9A63" />
  </svg>
);
const SkyBg: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  const d = lin(t, a, a + 5);
  return (
    <AbsoluteFill style={{ background: `linear-gradient(180deg, ${SKY_T} 0%, ${SKY_B} 72%)` }}>
      <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", left: 0, top: 0 }}>
        <g transform={`translate(${-80 * d} 0)`}>
          <path d="M-220 1560 L-40 1380 L170 1330 L330 1470 L540 1250 L760 1460 L900 1350 L1120 1470 L1300 1560 Z" fill="#7C8FB0" />
        </g>
        <g transform={`translate(${70 * d} 0)`}>
          <path d="M-220 1640 L-220 1500 L-20 1450 L250 1400 L420 1520 L640 1360 L880 1540 L1140 1420 L1300 1500 L1300 1640 Z" fill="#33415E" />
        </g>
        <rect x={0} y={1600} width={1080} height={320} fill="#8FB0C6" />
        <rect x={0} y={1600} width={1080} height={10} fill="#A9C6D8" />
      </svg>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `translateX(${-130 * d}px)` }}>
        <Cactus x={70} y={1640} h={230} />
        <Cactus x={250} y={1620} h={130} flip />
        <Cactus x={820} y={1650} h={260} flip />
        <Cactus x={700} y={1615} h={110} />
      </div>
    </AbsoluteFill>
  );
};

// ───────── peças da marca ─────────
const Logo: React.FC<{ t: number; at: number; w: number; slam?: boolean; sub?: boolean }> = ({ t, at, w, slam, sub = true }) => {
  const s = sp(t, at, slam ? 14 : 18, slam ? 200 : 160);
  const r = sp(t, at + 0.12, 200, 160);
  const dt = sp(t, at + 0.3, 12, 220);
  const sb = k(t, at + 0.42, 0.4);
  const fs = w / 5.3;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{ display: "flex", alignItems: "center", fontFamily: MS, fontWeight: 700, fontSize: fs, lineHeight: 1, letterSpacing: "-0.02em" }}>
        <span style={{ display: "inline-block", fontWeight: 900, fontSize: fs * 1.16, background: `linear-gradient(160deg, ${CYAN_L} 0%, ${CYAN} 45%, ${BLUE} 100%)`, WebkitBackgroundClip: "text", color: "transparent",
          transform: `scale(${slam ? 2.6 - 1.6 * s : 0.5 + 0.5 * s}) rotate(${(1 - s) * (slam ? -120 : -30)}deg)`, opacity: Math.min(1, s * 3) }}>C</span>
        <span style={{ display: "inline-block", overflow: "hidden", padding: "0.04em 0.02em" }}>
          <span style={{ display: "inline-block", color: WHITE, transform: `translateX(${(1 - r) * -105}%)` }}>limatize</span>
        </span>
        <span style={{ display: "flex", flexDirection: "column", gap: fs * 0.12, marginLeft: fs * 0.12, marginTop: fs * 0.18 }}>
          {[0, 1].map((i) => <span key={i} style={{ width: fs * 0.17, height: fs * 0.17, borderRadius: "50%", background: i ? BLUE : CYAN, transform: `scale(${dt})` }} />)}
        </span>
      </div>
      {sub && <div style={{ alignSelf: "flex-end", marginTop: fs * 0.12, marginRight: fs * 0.3, fontFamily: MS, fontWeight: 800, fontSize: fs * 0.17, letterSpacing: "0.04em", color: WHITE, opacity: sb, transform: `translateY(${(1 - sb) * 10}px)` }}>REFRIGERAÇÃO - CLIMATIZAÇÃO</div>}
    </div>
  );
};

// ícone em vidro ciano (como no vídeo anterior)
const Tile: React.FC<{ t: number; at: number; size: number; children: React.ReactNode; dark?: boolean }> = ({ t, at, size, children, dark }) => {
  const s = sp(t, at, 13, 200);
  return (
    <div style={{ width: size, height: size, borderRadius: size * 0.26, flex: "none", position: "relative",
      background: dark ? `linear-gradient(160deg, #2C4F7C, ${NAVY_D})` : `linear-gradient(160deg, #9BE4FA 0%, ${CYAN} 50%, ${BLUE} 100%)`,
      boxShadow: `inset 0 ${size * 0.04}px ${size * 0.06}px rgba(255,255,255,0.55), inset 0 -${size * 0.05}px ${size * 0.08}px rgba(0,40,90,0.35), 0 ${size * 0.12}px ${size * 0.3}px rgba(5,20,45,0.4)`,
      border: "2px solid rgba(255,255,255,0.45)", display: "flex", alignItems: "center", justifyContent: "center",
      opacity: Math.min(1, s * 3), transform: `scale(${s}) rotate(${(1 - s) * -14}deg)` }}>
      <svg width={size * 0.56} height={size * 0.56} viewBox="0 0 100 100" fill="none" stroke={WHITE} strokeWidth={8} strokeLinecap="round" strokeLinejoin="round">{children}</svg>
    </div>
  );
};
const I = {
  snow: <g><path d="M50 8 V92 M14 29 L86 71 M14 71 L86 29" /><path d="M38 14 L50 24 L62 14 M38 86 L50 76 L62 86 M12 44 L24 36 L20 22 M88 56 L76 64 L80 78 M12 56 L24 64 L20 78 M88 44 L76 36 L80 22" /></g>,
  trophy: <g><path d="M30 14 H70 V40 A20 20 0 0 1 30 40 Z" /><path d="M30 22 H16 A14 14 0 0 0 32 46 M70 22 H84 A14 14 0 0 1 68 46" /><path d="M50 60 V76 M34 88 H66 M38 88 V78 H62 V88" /></g>,
  gift: <g><rect x={14} y={38} width={72} height={20} rx={4} /><path d="M20 58 V88 H80 V58 M50 38 V88" /><path d="M50 38 C40 20 22 22 28 34 C32 40 44 38 50 38 C56 38 68 40 72 34 C78 22 60 20 50 38" /></g>,
  wrench: <path d="M62 12 A22 22 0 0 0 46 44 L14 76 A8 8 0 0 0 26 88 L58 56 A22 22 0 0 0 88 38 L74 46 L60 40 L56 26 Z" />,
  drop: <g><path d="M50 10 C34 34 22 48 22 62 A28 28 0 0 0 78 62 C78 48 66 34 50 10 Z" /><path d="M36 64 A14 14 0 0 0 50 78" /></g>,
  gear: <g><circle cx={50} cy={50} r={14} /><path d="M50 10 V22 M50 78 V90 M10 50 H22 M78 50 H90 M22 22 L30 30 M70 70 L78 78 M22 78 L30 70 M70 30 L78 22" /></g>,
  heart: <path d="M50 84 C20 64 10 48 10 34 A20 20 0 0 1 50 26 A20 20 0 0 1 90 34 C90 48 80 64 50 84 Z" />,
  check: <path d="M20 52 L42 72 L82 30" />,
  ticket: <g><path d="M10 30 H90 V42 A8 8 0 0 0 90 58 V70 H10 V58 A8 8 0 0 0 10 42 Z" /><path d="M64 30 V70" strokeDasharray="4 8" /></g>,
};

// faixa de lettering na parte de baixo das cenas com vídeo
const Band: React.FC<{ t: number; at: number; out?: number; top?: number; children: React.ReactNode; color?: string }> = ({ t, at, out, top = 1400, children, color = CYAN }) => {
  if (t < at - 0.02 || (out !== undefined && t > out + 0.2)) return null;
  const s = sp(t, at, 200, 190);
  const o = out === undefined ? 0 : k(t, out, 0.16);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", justifyContent: "center", opacity: 1 - o, transform: `translateY(${o * 30}px)` }}>
      <div style={{ padding: "26px 54px 32px", borderRadius: 34, background: color, boxShadow: "0 24px 60px rgba(5,20,45,0.45)", clipPath: `inset(0 ${(1 - s) * 50}% 0 ${(1 - s) * 50}% round 34px)`,
        display: "flex", flexDirection: "column", alignItems: "center" }}>{children}</div>
    </div>
  );
};

// trecho do vídeo da entrega em tela cheia, com soco curto na troca
const Clip: React.FC<{ t: number; a: number; b: number; src: number; z?: [number, number] }> = ({ t, a, b, src, z = [1.03, 1.1] }) => {
  if (t < a || t >= b) return null;
  const punch = 1 + 0.07 * (1 - k(t, a, 0.32));
  const zz = z[0] + (z[1] - z[0]) * lin(t, a, b);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: "#000" }}>
      <Sequence from={Math.round(a * CZ_FPS)} durationInFrames={Math.round((b - a) * CZ_FPS) + 1} layout="none">
        <OffthreadVideo src={VID} startFrom={Math.round(src * CZ_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(zz * punch).toFixed(4)})` }} />
      </Sequence>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(8,18,36,0) 55%, rgba(8,18,36,0.55) 100%)" }} />
    </AbsoluteFill>
  );
};

// ar-condicionado split desenhado, com laço de presente e vento saindo
const AirCon: React.FC<{ t: number; at: number; w: number }> = ({ t, at, w }) => {
  const s = sp(t, at, 15, 160);
  const bow = sp(t, at + 0.35, 11, 220);
  const air = lin(t, at + 0.4, at + 3.6);
  const h = w * 0.34;
  return (
    <div style={{ position: "relative", width: w, height: h + 240, opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * -500}px)` }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: w, height: h, borderRadius: h * 0.28, background: "linear-gradient(180deg, #FFFFFF 0%, #E6EEF4 100%)",
        boxShadow: "0 30px 70px rgba(12,26,49,0.35), inset 0 -6px 0 rgba(20,40,74,0.08)" }}>
        <div style={{ position: "absolute", left: w * 0.06, right: w * 0.06, bottom: h * 0.2, height: h * 0.1, borderRadius: 8, background: "#C8D6E2" }} />
        <div style={{ position: "absolute", right: w * 0.08, top: h * 0.24, width: h * 0.1, height: h * 0.1, borderRadius: "50%", background: CYAN }} />
        <div style={{ position: "absolute", left: w * 0.07, top: h * 0.2, fontFamily: MS, fontWeight: 800, fontSize: h * 0.16, color: NAVY, letterSpacing: "-0.02em" }}>Climatize</div>
        {/* fita vermelha do presente */}
        <div style={{ position: "absolute", left: w * 0.62, top: -6, width: w * 0.07, height: h + 12, background: "#D8232A", transform: `scaleY(${bow})`, transformOrigin: "50% 0" }} />
      </div>
      <svg width={w * 0.34} height={w * 0.22} viewBox="0 0 100 64" style={{ position: "absolute", left: w * 0.655 - w * 0.17, top: -w * 0.15, transform: `scale(${bow})`, transformOrigin: "50% 90%" }}>
        <path d="M50 54 C30 20 4 18 10 40 C14 54 36 54 50 54 C64 54 86 54 90 40 C96 18 70 20 50 54 Z" fill="#E5333A" />
        <circle cx={50} cy={52} r={9} fill="#B71C22" />
      </svg>
      <svg width={w} height={240} viewBox={`0 0 ${w} 240`} style={{ position: "absolute", left: 0, top: h + 10 }}>
        {[0.2, 0.4, 0.6, 0.8].map((x, i) => {
          const ph = (air * 2.2 + i * 0.25) % 1;
          return <path key={i} d={`M${w * x} 10 q ${-30} 60 0 110 t 0 110`} stroke="rgba(255,255,255,0.9)" strokeWidth={9} strokeLinecap="round" fill="none"
            strokeDasharray="60 400" strokeDashoffset={-ph * 300} opacity={Math.min(1, air * 6) * (1 - ph * 0.6)} />;
        })}
      </svg>
    </div>
  );
};

const WaIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <path d="M50 12 a36 36 0 0 0 -31 54 l-5 20 20 -5 a36 36 0 1 0 16 -69 z" fill="none" stroke="#fff" strokeWidth={7} strokeLinejoin="round" />
    <path d="M37 33 c-3 5 0 13 7 20 s15 10 20 7 l2 -6 -8 -5 -4 4 c-4 -1 -8 -5 -9 -9 l4 -4 -5 -8 z" fill="#fff" />
  </svg>
);
const IgIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <defs><linearGradient id="igz" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#FEDA75" /><stop offset="0.35" stopColor="#FA7E1E" /><stop offset="0.65" stopColor="#D62976" /><stop offset="1" stopColor="#4F5BD5" /></linearGradient></defs>
    <rect x={4} y={4} width={92} height={92} rx={26} fill="url(#igz)" />
    <rect x={24} y={24} width={52} height={52} rx={16} fill="none" stroke="#fff" strokeWidth={7} />
    <circle cx={50} cy={50} r={12} fill="none" stroke="#fff" strokeWidth={7} />
    <circle cx={67} cy={33} r={4} fill="#fff" />
  </svg>
);
const Pill: React.FC<{ t: number; at: number; bg: string; children: React.ReactNode; glass?: boolean }> = ({ t, at, bg, children, glass }) => {
  const s = sp(t, at, 15, 190);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 24, padding: "26px 52px", borderRadius: 80, background: bg, border: glass ? "2px solid rgba(255,255,255,0.28)" : "none",
      boxShadow: glass ? "0 20px 50px rgba(0,0,0,0.3)" : "0 24px 60px rgba(37,211,102,0.3)", opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 120}px) scale(${0.85 + 0.15 * s})` }}>{children}</div>
  );
};

// ───────── vídeo ─────────
export const ClimatizeSorteio: React.FC = () => {
  const t = useCurrentFrame() / CZ_FPS;
  return (
    <AbsoluteFill style={{ background: NAVY_D, overflow: "hidden" }}>
      {/* 0 · logo batendo */}
      <Scene t={t} a={0} b={0.95} tr="none" bg={NAVY} cam={[1.12, 1.0]}>
        <NavyBg />
        <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}><Logo t={t} at={0.03} w={860} slam /></AbsoluteFill>
      </Scene>

      {/* 1 · trecho da entrega: "parabéns, Jane, você acaba de ganhar um ar-condicionado" (áudio original) */}
      <Scene t={t} a={0.95} b={6.35} tr="iris" bg="#000" cam={[1, 1]}>
        <Clip t={t} a={0.95} b={3.1} src={13.25} />
        <Clip t={t} a={3.1} b={4.7} src={40.3} />
        <Clip t={t} a={4.7} b={6.75} src={44.3} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 110, display: "flex", justifyContent: "center", opacity: k(t, 1.2, 0.4) }}>
          <div style={{ padding: "18px 34px 14px", borderRadius: 30, background: "rgba(12,26,49,0.78)" }}><Logo t={t} at={1.2} w={300} sub={false} /></div>
        </div>
        <Band t={t} at={1.1} out={2.95}>
          <Line t={t} size={92} words={[["Parabéns,", 1.12], ["Jane!", 1.78, true]]} accent={NAVY} />
        </Band>
        <Band t={t} at={3.15} top={1340}>
          <Line t={t} size={54} color={NAVY} words={[["ganhou", 3.2], ["um", 3.3]]} />
          <Line t={t} size={98} words={[["ar-condicionado", 3.42, true]]} accent={WHITE} />
        </Band>
        {t > 5.45 && (() => {
          const s = sp(t, 5.49, 12, 230);
          return (
            <div style={{ position: "absolute", left: 0, right: 0, top: 1660, display: "flex", justifyContent: "center" }}>
              <div style={{ padding: "14px 36px 16px", borderRadius: 40, background: WHITE, fontFamily: MS, fontWeight: 800, fontSize: 52, color: NAVY, opacity: Math.min(1, s * 3), transform: `scale(${0.5 + 0.5 * s})` }}>9.000 BTUs</div>
            </div>
          );
        })()}
      </Scene>

      {/* 2 · já saiu a primeira ganhadora */}
      <Scene t={t} a={6.35} b={10.65} tr="circle" bg={NAVY} cam={[1.0, 1.13]} drift={-40}>
        <NavyBg />
        <Col top={360}><Tile t={t} at={6.5} size={230}>{I.trophy}</Tile></Col>
        <Col top={700} gap={6}>
          <Line t={t} size={64} words={[["Já", 6.48], ["saiu", 6.76], ["a", 7.1]]} />
          <Line t={t} size={150} words={[["1ª", 7.2]]} />
          <Line t={t} size={132} words={[["ganhadora", 7.68, true]]} />
          <div style={{ height: 18 }} />
          <Line t={t} size={64} words={[["do", 8.18], ["ar-condicionado", 8.4]]} />
        </Col>
        <Col top={1420} op={k(t, 9.32, 0.3)}><Logo t={t} at={9.32} w={520} /></Col>
